    },
    {
      "name": "Kids & Me Drop-In Neighbourhood Groups",
      "age_fit": "babies or children up to 6 years of age, with a parent or caregiver",
      "when": "Weekly, 1.5 hours. Follows the school calendar from the second week of September. Closed for the December/January holidays and statutory holidays.",
      "price": "Free",
